const isCurrentReadingVocabularyReserved = `-- name: IsCurrentReadingVocabularyReserved :one
SELECT EXISTS (
  SELECT 1 FROM primary_goal_snapshots ps
  JOIN primary_goal_snapshot_vocabulary pv
    ON pv.owner_id = ps.owner_id AND pv.snapshot_id = ps.id
  WHERE ps.owner_id = $1 AND ps.language = $2
    AND ps.released_at IS NULL AND pv.language = $2
    AND pv.canonical_lemma = $3 AND pv.upos = $4
)
`

type IsCurrentReadingVocabularyReservedParams struct {
	Owner          string
	Language       string
	CanonicalLemma string
	Upos           string
}

func (q *Queries) IsCurrentReadingVocabularyReserved(ctx context.Context, arg IsCurrentReadingVocabularyReservedParams) (bool, error) {
	row := q.db.QueryRow(ctx, isCurrentReadingVocabularyReserved,
		arg.Owner,
		arg.Language,
		arg.CanonicalLemma,
		arg.Upos,
	)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const listCurrentReadingSnapshotCandidates = `-- name: ListCurrentReadingSnapshotCandidates :many
SELECT sc.owner_id::text AS owner_id,
       sc.corpus_id, sc.language, sc.canonical_lemma, sc.upos,
       sc.occurrence_count, sc.observed_forms, sc.eligible_sentence_refs,
       sc.provenance, sc.selected_at,
       COALESCE(first_seen.start_offset, 9223372036854775807::bigint)::bigint AS first_encounter
FROM selection_candidates sc
LEFT JOIN LATERAL (
  SELECT MIN(COALESCE(ref->'location'->>'start_offset', ref->'location'->>'StartOffset', ref->'Location'->>'StartOffset')::bigint) AS start_offset
  FROM jsonb_array_elements(sc.eligible_sentence_refs) ref
) first_seen ON true
WHERE sc.owner_id = $1
  AND sc.corpus_id = $2
  AND sc.language = $3
  AND sc.occurrence_count >= 2
ORDER BY sc.language, sc.canonical_lemma, sc.upos
`

type ListCurrentReadingSnapshotCandidatesParams struct {
	Owner    string
	Corpus   string
	Language string
}

type ListCurrentReadingSnapshotCandidatesRow struct {
	OwnerID              string
	CorpusID             string
	Language             string
	CanonicalLemma       string
	Upos                 string
	OccurrenceCount      int
	ObservedForms        []byte
	EligibleSentenceRefs []byte
	Provenance           []byte
	SelectedAt           time.Time
	FirstEncounter       int64
}

func (q *Queries) ListCurrentReadingSnapshotCandidates(ctx context.Context, arg ListCurrentReadingSnapshotCandidatesParams) ([]ListCurrentReadingSnapshotCandidatesRow, error) {
	rows, err := q.db.Query(ctx, listCurrentReadingSnapshotCandidates, arg.Owner, arg.Corpus, arg.Language)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListCurrentReadingSnapshotCandidatesRow{}
	for rows.Next() {
		var i ListCurrentReadingSnapshotCandidatesRow
		if err := rows.Scan(
			&i.OwnerID,
			&i.CorpusID,
			&i.Language,
			&i.CanonicalLemma,
			&i.Upos,
			&i.OccurrenceCount,
			&i.ObservedForms,
			&i.EligibleSentenceRefs,
			&i.Provenance,
			&i.SelectedAt,
			&i.FirstEncounter,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

